query R65FlowerVariantCountercheck($oldVariant: ID!, $currentVariant: ID!) {
  oldVariant: node(id: $oldVariant) { id ... on ProductVariant { sku price product { id } } }
  currentVariant: node(id: $currentVariant) { id ... on ProductVariant { sku price product { id } } }
}
